// Author: Aldrin Payopay <aldrin.gdf@gmail.com>
declare name "Bloom Oscillator";
declare author "Aldrin Payopay";
import("stdfaust.lib");
frequency = hslider("frequency[unit:Hz][scale:log]",220,30,2000,0.1) : si.smoo;
ratio = hslider("ratio",2,0.25,8,0.01) : si.smoo;
index = hslider("index",0.3,0,3,0.01) : si.smoo;
spread = hslider("spread[unit:Hz]",1.5,0,12,0.1) : si.smoo;
level = hslider("level[unit:dB]",-18,-48,-6,0.1) : ba.db2linear : si.smoo;
voice(detune) = os.osc(max(1,frequency+detune+os.osc(frequency*ratio)*frequency*index)) * level;
process = voice(0-spread), voice(spread);

